// dsh-web-open 自包含补丁模块(尾插方案 2026-08-16)
// 由 main.js 末尾 require 加载;无锚点依赖——DSH 更新后由插件自愈(ensurePatched)重新复制本文件 + 尾插加载行
const { app, BrowserWindow, BrowserView, ipcMain, shell, Notification, dialog, net, Tray, nativeImage, session } = require('electron');
const path = require('path');
const fs = require('fs');
const http = require('http');
const os = require('os');
const child_process = require('child_process');
const userDataDir = app.getPath('userData');
function log(prefix, msg) { try { console.log('[' + prefix + ']', msg); } catch {} }
global.__webboxLog = log;
// ── 性能探针(排查启动卡顿,临时) ──


const webWindows = new Set(); // dsh-web-open 内嵌网页窗口集合

// ── 应用层 DNS 直连(2026-08-16 v3):动态 resolve-host(每次解析读缓存,缓存更新即生效);启动读缓存仅作准备
const DNSMAP_CACHE = path.join(userDataDir, 'dsh-web-open-dnsmap.json');
const pyDoh = "import socket\nPOOL=['140.82.114.4','140.82.112.4','140.82.113.4','140.82.116.4','140.82.121.4','20.205.243.166','20.205.243.168']\ndef ok(ip,port=443,t=2):\n try:\n  s=socket.create_connection((ip,port),timeout=t); s.close(); return True\n except: return False\nfor ip in POOL:\n if ok(ip): print('MAP github.com %s'%ip); break";
try {
  const _c = JSON.parse(fs.readFileSync(DNSMAP_CACHE, 'utf8'));
  if (_c && _c.map) {
    // host-resolver-rules 已弃用:静态快照会锁死失效 IP;改用动态 resolve-host(每次解析读缓存)
    log('webbox', 'DNS MAP 缓存注入: ' + _c.map);
  }
} catch (e) { /* 无缓存:走系统 DNS */ }
function doRecheck(cb) {
  try {
    child_process.execFile('python', ['-c', pyDoh], { timeout: 20000, windowsHide: true }, (err, stdout) => {
      const _map = stdout ? stdout.toString().trim() : '';
      if (!err && _map) {
        try { fs.writeFileSync(DNSMAP_CACHE, JSON.stringify({ t: Date.now(), map: _map }), 'utf8'); } catch (e) {}
        log('webbox', 'DNS MAP 已更新: ' + _map);
      }
      if (cb) { try { cb(); } catch (e) {} }
    });
  } catch (e) { if (cb) { try { cb(); } catch (e2) {} } }
}
app.whenReady().then(() => {
  // 🐛 GitHub 新版 Download zip 按钮 href 是 zip/refs/... 格式(该路径 404)→ 重写为 archive/...zip(302→codeload→下载)
  try {
    const _ss = require('electron').session;
    _ss.fromPartition('persist:dsh-webbox').webRequest.onBeforeRequest({ urls: ['https://github.com/*/zip/*'] }, (details, cb) => {
      try {
        const m = details.url.match(/^https:\/\/github\.com\/([^\/]+\/[^\/]+)\/zip\/(.+)$/);
        if (m) { cb({ redirectURL: 'https://github.com/' + m[1] + '/archive/' + m[2] + '.zip' }); return; }
      } catch (e) {}
      cb({});
    });
  } catch (e) {}
  try {
    session.defaultSession.on('resolve-host', (details, callback) => {
      try {
        if (details.host !== 'github.com') { callback({}); return; } // 只拦主站;codeload/raw/api 走系统 DNS 多 IP 轮换(像系统浏览器一样下载成功)
        const _m2 = JSON.parse(fs.readFileSync(path.join(userDataDir, 'dsh-web-open-dnsmap.json'), 'utf8')).map || '';
        const _ip2 = (_m2.match(/MAP github\.com ([0-9.]+)/) || [])[1] || '140.82.114.4';
        callback({ ip: _ip2 });
      } catch (e) { callback({}); }
    });
  } catch (e) { log('webbox', 'resolve-host 注册失败: ' + ((e && e.message) || e)); }
  try {
    const _age = Date.now() - (JSON.parse(fs.readFileSync(DNSMAP_CACHE, 'utf8')).t || 0);
    if (_age < 6 * 3600 * 1000) return; // 缓存新鲜(6h 内):不重测,零子进程
  } catch (e) {}
  setTimeout(() => doRecheck(), 15000);
});

